// === Tab: Bubble ===
class Bubble {
	constructor() {
		this.position_x = random(windowWidth);
		this.x_disp = random(100);
		this.position_y = windowHeight;
		this.distance_to_mouse = 0;
		this.reaction_vector = createVector(1, 1);

		var a = random(0.01, 5);
		var b = random(0.01, 5) > a ? a : b;

		this.rise_rate = -b;
		this.size = random(20, 100);
		this.color = color(random(100), random(250), 255);
		this.color_alpha = color(random(100), random(250), 255, 50);
		this.thickness = (map(this.size, 20, 100, 1, 6));
		this.size_mod_x = 0;
		this.size_mod_y = 0;
	}

	draw(mouse) {
		this.size_mod_x = cos(this.x_disp * 20) * 5;
		this.size_mod_y = sin(this.x_disp * 17) * 5;

		if (this.position_y < -50) {
			this.position_y = windowHeight + this.size;
		}

		if (this.position_x < -this.size) {
			this.position_x = windowWidth + this.size;

		} else if (this.position_x > windowWidth + this.size) {
			this.position_x = -this.size;
		}

		this.position_y += this.rise_rate;
		this.x_disp += 0.01;
		this.position_x = this.position_x + ((noise(this.x_disp) - 0.5) * 10);

		this.distance_to_mouse = dist(this.position_x, this.position_y, mouse.x, mouse.y);			// Reaction to the mouse
		if (this.distance_to_mouse < (this.size - 30)) {
			this.reaction_vector.x = mouse.x - this.position_x;
			this.reaction_vector.y = mouse.y - this.position_y;

		} else {
			this.reaction_vector.x = 0;
			this.reaction_vector.y = 0;
		}

		this.reaction_vector.mult(0.8);

		this.position_x = this.position_x - this.reaction_vector.x;
		this.position_y = this.position_y - this.reaction_vector.y;

		strokeWeight(this.thickness);
		stroke(this.color);
		fill(this.color_alpha);
		ellipse(this.position_x, this.position_y, this.size + this.size_mod_x, this.size + this.size_mod_y);

		var buffer_x = (0.2 * this.size) + (this.size_mod_x / 2);
		var buffer_y = (0.2 * this.size) + (this.size_mod_y / 2);

		stroke(255);
		arc(this.position_x + buffer_x, this.position_y - buffer_y, this.size / 5, this.size / 5, TWO_PI - (PI / 2), TWO_PI);
	}
}

